INSERT INTO toys (id, name, line, series_id, release_date, sort_index, image_url, amiibo_id, metadata_json, verified, scl_url, region, type, series) VALUES ('bash-skylanders-spyro-s-adventure-241', 'Bash', 'Skylanders', 'skylanders-spyro-s-adventure', '2011-10-01', 5, 'https://skylanderscharacterlist.com/wp-content/uploads/2014/03/Bash.png', NULL, '{"element":"Earth","series":"Series 1","released_with":"Spyro''s Adventure","description":"More Bash Figures:\n\nBash (Series 2)\n\nBlue\n\nLegendary\n\nMini\nBash is one of the 32 original characters. He was released in Wave 1 in October 2011.\nSeries 1 Bash was available in a Single Pack as well as a Triple Pack (with Eruptor and Chop Chop).\nAlthough you may not be able to find him in stores, he is quite common in the resale market (especially if you don''t mind buying used figures)."}', 1, 'https://skylanderscharacterlist.com/bash-series-1/', 'USA, Europe, Australia', 'Series 1', '1') ON CONFLICT(id) DO NOTHING;
