INSERT INTO toys (id, name, line, series_id, release_date, sort_index, image_url, amiibo_id, metadata_json, verified, scl_url, region, type, series) VALUES ('anvil-rain-skylanders-spyro-s-adventure-287', 'Anvil Rain', 'Skylanders', 'skylanders-spyro-s-adventure', '2011-10-16', 42, 'https://skylanderscharacterlist.com/wp-content/uploads/2013/07/AnvilRain.png', NULL, '{"element":null,"series":null,"released_with":"Spyro''s Adventure","description":"Timing: ~ 45 seconds\nEffect: Anvils will randomly rain down from the sky in the area surrounding your Skylander. The anvils will damage enemies and destroy breakables.\nNote: Anvil Rain can only be used for 45 seconds per level. If you remove Anvil Rain from the Portal before the time is up, you can use the remaining time later in the level. However, the timer will not refill until you start a new level."}', 1, 'https://skylanderscharacterlist.com/anvil-rain/', 'USA, Europe, Australia', 'Magic Item', '1') ON CONFLICT(id) DO NOTHING;
INSERT INTO toys (id, name, line, series_id, release_date, sort_index, image_url, amiibo_id, metadata_json, verified, scl_url, region, type, series) VALUES ('darklight-crypt-skylanders-spyro-s-adventure-281', 'Darklight Crypt', 'Skylanders', 'skylanders-spyro-s-adventure', '2011-10-16', 43, 'https://skylanderscharacterlist.com/wp-content/uploads/2013/07/DarklightCrypt.png', NULL, '{"element":null,"series":null,"released_with":"Spyro''s Adventure","description":"Timing (in Hub): Instant\nEffect (in Hub): The Darklight Crypt Level will be unlocked and available for you to play at any time.\nTiming (in any Level): After a 4 second delay, “Ghosts” will rain down for 7 seconds. This is followed immediately by a final attack.\nEffect (in any Level): After the delay, the raining “Ghosts” will cause damage to any enemies and breakables they land on. Immediately following the rain, the Darklight Crypt will unleash a final attack that emanates from your Skylander. This final attack deals 999 damage to anything it hits which should finish off any enemy.\nNote: Darklight Crypt can only be used once per level. Even if you take the figure off the Portal and put it back on, it will have no effect until you start a new level."}', 1, 'https://skylanderscharacterlist.com/darklight-crypt/', 'USA, Europe, Australia', 'Magic Item', '1') ON CONFLICT(id) DO NOTHING;
